uniform float iTime;
uniform vec2 iResolution;
uniform vec4 iMouse;
uniform sampler2D iChannel0;

// Parameter mappings
uniform float u_speed;
uniform float u_scale;
uniform float u_intensity;
uniform float u_color_cycle;
uniform float u_layers;
uniform float u_density;
uniform float u_connection_radius;
uniform float u_pulse_intensity;
uniform float u_color_base;
uniform float u_color_pulse;

out vec4 fragColor;

// --- Helper Functions ---

mat2 rot(float a) {
    float s = sin(a), c = cos(a);
    return mat2(c, -s, s, c);
}

float hash21(vec2 p) {
    p = fract(p * vec2(123.34, 456.21));
    p += dot(p, p + 45.32);
    return fract(p.x * p.y);
}

vec2 hash22(vec2 p) {
    float n = hash21(p);
    return vec2(n, hash21(p + n));
}

// 2D Value Noise for organic cell spawning
float vnoise(vec2 p) {
    vec2 i = floor(p);
    vec2 f = fract(p);
    f = f * f * (3.0 - 2.0 * f);
    float a = hash21(i);
    float b = hash21(i + vec2(1.0, 0.0));
    float c = hash21(i + vec2(0.0, 1.0));
    float d = hash21(i + vec2(1.0, 1.0));
    return mix(mix(a, b, f.x), mix(c, d, f.x), f.y);
}

// Calculates the "Life" (Growth scale) of a cell based on radial outward expansion
float getLife(vec2 cellId, float t) {
    float r = length(cellId);

    // Direction vector pushing outward from the center
    vec2 dir = (r > 0.001) ? (cellId / r) : vec2(0.0);

    // By subtracting (dir * t), the noise field literally travels outward, spawning new cells
    float n = vnoise(cellId * 0.2 - dir * t * 0.5 + vec2(t * 0.1));

    // Core bias keeps the center permanently dense, while edges wither and regrow
    float coreBias = exp(-r * 0.08);

    // Returns a growth factor between 0.0 (dead) and 1.0 (fully grown)
    return smoothstep(0.3, 0.6, n * coreBias);
}

float distLine(vec2 p, vec2 a, vec2 b) {
    vec2 pa = p - a, ba = b - a;
    float h = clamp(dot(pa, ba) / dot(ba, ba), 0.0, 1.0);
    return length(pa - ba * h);
}

vec3 hsv2rgb(vec3 c) {
    vec4 K = vec4(1.0, 2.0 / 3.0, 1.0 / 3.0, 3.0);
    vec3 p = abs(fract(c.xxx + K.xyz) * 6.0 - K.www);
    return c.z * mix(K.xxx, clamp(p - K.xxx, 0.0, 1.0), c.y);
}

// Evaluates Connections between reproducing nodes
void evalConnection(vec2 f, vec2 p1, float life1, vec2 offs, vec2 dir, vec2 id, float t, float connRadius, inout vec4 lineData) {
    vec2 cellId = id + offs;
    vec2 neighborId = cellId + dir;

    float life2 = getLife(neighborId, t);

    // Only connect if both the current node and the neighbor are alive
    if (life2 > 0.0) {
        vec2 p2 = offs + dir + 0.5 + 0.3 * sin(t * 1.5 + hash22(neighborId) * 6.28);
        float dConn = distance(p1, p2);

        if (dConn < connRadius) {
            float dLine = distLine(f, p1, p2);

            // The connection is only as strong as its weakest cell (creates organic growth)
            float lineAlpha = min(life1, life2); 

            float px = 0.015;
            float thickness = 0.012 * lineAlpha; // Line grows thicker as the cells mature
            float shape = smoothstep(thickness + px, thickness, dLine);

            if (shape > 0.0) {
                // Outward sweeping data pulse
                float r = length(cellId);
                float pulse = smoothstep(0.8, 1.0, sin(r * 0.8 - t * 6.0));

                // Fade out lines that are stretching too far
                pulse *= smoothstep(connRadius, connRadius * 0.7, dConn);

                // Accumulate the line shape and the pulse intensity
                lineData.a = max(lineData.a, shape * lineAlpha);
                lineData.r = max(lineData.r, pulse * shape * lineAlpha);
            }
        }
    }
}

void main() {
    vec2 uv = (gl_FragCoord.xy - 0.5 * iResolution.xy) / iResolution.y;
    vec2 uv0 = uv;

    vec2 mouseOffset = (iMouse.z > 0.0) ? (iMouse.xy / iResolution.xy - 0.5) : vec2(0.0);

    float spd = (u_speed <= 0.0) ? 0.3 : u_speed;
    float t = iTime * spd;

    // Breathing pulse
    float breathe = 1.0 + 0.05 * sin(t); 

    float scaleBase = (u_scale <= 0.0) ? 1.0 : u_scale;
    float layerCount = (u_layers <= 0.0) ? 5.0 : u_layers;
    float density = (u_density <= 0.0) ? 1.0 : u_density * 2.0; 
    float connRadius = ((u_connection_radius <= 0.0) ? 1.5 : u_connection_radius * 2.5) * breathe;
    float pulseInt = (u_pulse_intensity <= 0.0) ? 1.5 : u_pulse_intensity * 3.0;

    float hueBase = fract(0.55 + u_color_base + (t * u_color_cycle * 0.1));
    float huePulse = fract(0.10 + u_color_pulse + (t * u_color_cycle * 0.1));

    vec3 baseCol = hsv2rgb(vec3(hueBase, 0.65, 1.0));
    vec3 pulseCol = hsv2rgb(vec3(huePulse, 0.8, 1.0));

    // Clean Gradient Background
    vec3 bgCenter = baseCol * 0.12; 
    vec3 bgEdge = vec3(0.015, 0.02, 0.03);
    vec3 finalColor = mix(bgCenter, bgEdge, length(uv0) * 1.2);

    // Layered Alpha Compositing
    for(int i = 0; i < 5; i++) {
        float fi = float(i);
        if(fi >= layerCount) break;

        float z = fract(fi * 0.2 + t * 0.05); // Slow layer drifting
        float fade = smoothstep(0.0, 0.2, z) * smoothstep(1.0, 0.7, z);

        float size = mix(12.0, 1.0, z) * scaleBase * density;

        // Centered scaling (no continuous panning)
        vec2 layerUV = (uv + mouseOffset * (1.0 - z) * 0.5) * size;
        layerUV *= rot(z * 0.3 + fi); // Slight twist per layer

        vec2 id = floor(layerUV);
        vec2 f = fract(layerUV);

        float nodeMask = 0.0;
        vec4 lineData = vec4(0.0); // .a = alpha mask, .r = pulse intensity

        // 3x3 Neighborhood search
        for(int y = -1; y <= 1; y++) {
            for(int x = -1; x <= 1; x++) {
                vec2 offs = vec2(float(x), float(y));
                vec2 cellId = id + offs;

                // Determine if this cell is currently "alive"
                float life1 = getLife(cellId, t);

                if(life1 > 0.0) {
                    vec2 p1 = offs + 0.5 + 0.4 * sin(t * 1.5 + hash22(cellId) * 6.28);

                    // --- Render Animated Atom Node ---
                    float dNode = length(f - p1);
                    float rad = 0.07 * life1; // The node scales up organically as it is born
                    float px = 0.015;

                    float ring = smoothstep(rad + px, rad, dNode) - smoothstep(rad*0.6 + px, rad*0.6, dNode);
                    float core = smoothstep(rad*0.3 + px, rad*0.3, dNode);

                    // Accumulate the node shape
                    nodeMask = max(nodeMask, clamp(ring + core, 0.0, 1.0) * life1);

                    // --- Render Outward Connections ---
                    // Only looking forward/down to prevent double-drawing lines
                    evalConnection(f, p1, life1, offs, vec2(1.0, 0.0), id, t, connRadius, lineData);
                    evalConnection(f, p1, life1, offs, vec2(0.0, 1.0), id, t, connRadius, lineData);
                    evalConnection(f, p1, life1, offs, vec2(1.0, 1.0), id, t, connRadius, lineData);
                    evalConnection(f, p1, life1, offs, vec2(-1.0, 1.0), id, t, connRadius, lineData);
                }
            }
        }

        // --- Layer Compositing (Pure Alpha Blending) ---
        vec4 layerColor = vec4(0.0);

        // 1. Color the lines
        vec3 lCol = mix(baseCol, pulseCol, lineData.r * pulseInt);
        layerColor.rgb = lCol;
        layerColor.a = lineData.a;

        // 2. Color the nodes (Pure white atoms drawn OVER the lines)
        layerColor.rgb = mix(layerColor.rgb, vec3(1.0), nodeMask);
        layerColor.a = max(layerColor.a, nodeMask);

        // 3. Apply Z-Depth fade
        layerColor.a *= fade * 0.9; 

        // Blend Layer onto the final image
        finalColor = mix(finalColor, layerColor.rgb, layerColor.a);
    }

    // Subtle UI Vignette
    float vig = 1.0 - length(uv0) * 0.45;
    finalColor *= smoothstep(0.1, 1.0, vig);

    fragColor = vec4(finalColor, 1.0);
}
